using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class Tools
{
    [McpServerTool, Description("Greets the user by name.")]
    public static string Greet(
        [Description("The name of the person to greet")] string name) =>
        $"Hello, {name}! Welcome to the MCP web service.";

    [McpServerTool, Description("Returns the current server UTC time.")]
    public static string GetServerTime() =>
        DateTime.UtcNow.ToString("o");
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class Resources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the application configuration data.")]
    public static string GetAppSettings() =>
        JsonSerializer.Serialize(new
        {
            AppName = "McpWebService",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { EnableCaching = true, EnableLogging = true }
        }, new JsonSerializerOptions { WriteIndented = true });
}

